mapper.select:
select tp.plan_id, tp.plan_name, tp.major_id, tp.dept_id, tp.education_level, tp.plan_year, tp.total_credits, tp.publish_status, tp.publish_date, tp.version, tp.status, tp.del_flag, tp.create_by, tp.create_time, tp.update_by, tp.update_time, tp.remark,
       m.major_name as major_name, bd.dept_name as dept_name
from tpm_training_plan tp
left join sys_dept d on tp.dept_id = d.dept_id
left join brm_major m on tp.major_id = m.major_id
left join brm_department bd on tp.dept_id = bd.dept_id

    tp.del_flag = '0'
     and tp.plan_name like concat('%', #{planName}, '%')
     and tp.major_id = #{majorId}
     and tp.dept_id = #{deptId}
     and tp.education_level = #{educationLevel}
     and tp.publish_status = #{publishStatus}
     and tp.status = #{status}

    ${params.dataScope}

mapper.update:
update tpm_training_plan
plan_name = #{planName}, major_id = #{majorId}, dept_id = #{deptId}, education_level = #{educationLevel}, plan_year = #{planYear}, total_credits = #{totalCredits}, publish_status = #{publishStatus}, publish_date = #{publishDate}, version = #{version}, status = #{status}, update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark},
where plan_id = #{planId}

mapper.select:
select count(1) from tpm_training_plan
where del_flag = '0' and publish_status = '1'
  and major_id = #{majorId}
 and plan_year = #{planYear}
 and plan_id != #{excludePlanId}


where del_flag = '0' and major_id = #{majorId}
  and plan_year = #{planYear}
  and (education_level = #{educationLevel} or (education_level is null and #{educationLevel} is null))
order by plan_id asc limit 1
